<?php session_start(); require 'conectare.php'; $_SESSION['id_carte']??=[];$_SESSION['nr_buc']??=[];$_SESSION['pret']??=[];$_SESSION['titlu']??=[];$_SESSION['nume_autor']??=[];$action=$_GET['actiune']??'';
if($action==='adauga'){ $id=filter_input(INPUT_POST,'id_carte',FILTER_VALIDATE_INT)?:0; $s=$pdo->prepare('SELECT c.id_carte,c.titlu,c.pret,a.nume_autor FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_carte=?');$s->execute([$id]);if($b=$s->fetch()){ $found=array_search($id,array_map('intval',$_SESSION['id_carte']),true); if($found!==false) $_SESSION['nr_buc'][$found]++; else {$_SESSION['id_carte'][]=$id;$_SESSION['nr_buc'][]=1;$_SESSION['pret'][]=(float)$b['pret'];$_SESSION['titlu'][]=$b['titlu'];$_SESSION['nume_autor'][]=$b['nume_autor'];}} }
