include 'page_top.php';include 'meniu.php';$total=0.0;?><td valign="top"><h1>Cosul de cumparaturi</h1><form action="cos.php?actiune=modifica" method="post"><table border="1" cellspacing="0" cellpadding="4"><tr bgcolor="#f9f1e7"><td><b>Nr.bucati</b></td><td><b>Carte</b></td><td><b>Pret</b></td><td><b>Total</b></td></tr><?php foreach($_SESSION['id_carte'] as $i=>$id):$q=(int)$_SESSION['nr_buc'][$i];if($q<=0)continue;$line=(float)$_SESSION['pret'][$i]*$q;$total+=$line;?><tr><td><input type="number" min="0" name="noulnrbuc[<?=$i?>]" value="<?=$q?>" size="2"></td><td><b><?=h($_SESSION['titlu'][$i])?></b> de <?=h($_SESSION['nume_autor'][$i])?></td><td align="right"><?=number_format((float)$_SESSION['pret'][$i],2,',','.')?> lei</td><td align="right"><?=number_format($line,2,',','.')?> lei</td></tr><?php endforeach;?><tr><td colspan="3" align="right"><b>Total</b></td><td><b><?=number_format($total,2,',','.')?> lei</b></td></tr></table><input type="submit" value="Modifica"></form><p><a href="index.php">Continua cumparaturile</a> | <a href="casa.php">Mergi la casa</a></p></td><?php include 'page_bottom.php';?>
